'use client';

import { FormEvent, useEffect, useMemo, useState } from 'react';
import Link from 'next/link';
import type { User } from '@supabase/supabase-js';
import { buyNow, currentUser, loadActivities, loadListings, loadMarketAccess, placeBid, publishListing, sendMagicLink, signInWithPassword, signOut, signUpWithPassword, supplyBuyOrder } from '@/lib/market-api';
import { fallbackCatalog, loadMarketCatalog } from '@/lib/market-catalog';
import { currency, DEMO_ACTIVITY, DEMO_LISTINGS, PRODUCTS, quantity, REGIONS, type Activity, type Listing, type MarketAccess } from '@/lib/market';

type Modal = 'listing' | 'publish' | 'login' | 'activity' | null;
type ViewMode = 'cards' | 'book';
type SortMode = 'closing' | 'recent' | 'price-low' | 'price-high' | 'reputation';
type WebMcpTool = { name: string; title: string; description: string; inputSchema: Record<string, unknown>; annotations?: { readOnlyHint?: boolean; untrustedContentHint?: boolean }; execute: (input: unknown) => unknown | Promise<unknown> };

declare global { interface Document { readonly modelContext?: { registerTool: (tool: WebMcpTool, options?: { signal?: AbortSignal }) => void | Promise<void> } } }

const mechanismLabel = (listing: Listing) => listing.mechanism === 'FIXED' ? 'Compra inmediata' : listing.mechanism === 'AUCTION' ? 'Subasta abierta' : 'Orden de compra';
const sideLabel = (listing: Listing) => listing.side === 'BUY' ? 'Demanda' : 'Oferta';
const listingPrice = (listing: Listing) => listing.mechanism === 'AUCTION' ? listing.currentPrice ?? listing.price : listing.price;
const today = () => new Date().toLocaleDateString('en-CA', { timeZone: 'America/Santiago' });
const displayDate = (value: string) => new Intl.DateTimeFormat('es-CL', { day: 'numeric', month: 'short', year: 'numeric', timeZone: 'UTC' }).format(new Date(`${value}T12:00:00Z`));
const shortDate = (value: string) => new Intl.DateTimeFormat('es-CL', { day: '2-digit', month: 'short' }).format(new Date(value));

function remainingLabel(endsAt: string) {
  const milliseconds = new Date(endsAt).getTime() - Date.now();
  if (milliseconds <= 0) return 'Finalizada';
  const hours = Math.floor(milliseconds / 3_600_000);
  const minutes = Math.floor((milliseconds % 3_600_000) / 60_000);
  if (hours >= 24) return `${Math.floor(hours / 24)} d ${hours % 24} h`;
  return `${hours} h ${minutes} min`;
}

function LogoMark() { return <span className="logo-mark" aria-hidden="true"><i /><b /></span>; }
function VerifiedBadge({ compact = false }: { compact?: boolean }) { return <span className={`verified-badge${compact ? ' compact' : ''}`}><i>✓</i>{compact ? '' : 'Identidad verificada'}</span>; }

function ListingCard({ listing, onOpen }: { listing: Listing; onOpen: (listing: Listing) => void }) {
  const price = listingPrice(listing);
  const progress = Math.max(0, Math.min(100, (listing.availableQuantity / listing.totalQuantity) * 100));
  return <article className="listing-card">
    <div className="listing-card-head"><div><span className={`side-pill ${listing.side.toLowerCase()}`}>{sideLabel(listing)}</span><span className={`mechanism-pill ${listing.mechanism.toLowerCase()}`}>{mechanismLabel(listing)}</span></div><span className="closing-label">{listing.mechanism === 'AUCTION' ? `Cierra en ${remainingLabel(listing.endsAt)}` : `Hasta ${shortDate(listing.endsAt)}`}</span></div>
    <div className="product-row"><span className="product-monogram">{listing.product.slice(0, 2).toUpperCase()}</span><div><p>{listing.variety} · {listing.quality}</p><h3>{listing.product}</h3></div></div>
    <div className="price-block"><span>{listing.side === 'BUY' ? 'Precio máximo comprador' : listing.mechanism === 'AUCTION' ? 'Mejor oferta vigente' : 'Precio publicado'}</span><div><strong>{currency.format(price)}</strong><small>/ {listing.unit}</small></div></div>
    <div className="lot-progress"><div><span>Volumen disponible</span><strong>{quantity.format(listing.availableQuantity)} {listing.unit}</strong></div><i><b style={{ width: `${progress}%` }} /></i></div>
    <dl className="card-specs"><div><dt>Lote mínimo</dt><dd>{quantity.format(listing.minLot)} {listing.unit}</dd></div><div><dt>{listing.mechanism === 'AUCTION' ? 'Pujas' : 'Disponibilidad'}</dt><dd>{listing.mechanism === 'AUCTION' ? listing.bidCount : listing.availability}</dd></div></dl>
    <div className="participant-row"><div className="participant-avatar">{listing.seller.displayName.slice(0, 2).toUpperCase()}</div><div><strong>{listing.seller.displayName}</strong><span>{listing.seller.location} · {listing.seller.rating.toFixed(1)} ★</span></div><VerifiedBadge compact /></div>
    <button className="listing-open" onClick={() => onOpen(listing)}><span>{listing.side === 'BUY' ? 'Ofrecer abastecimiento' : listing.mechanism === 'AUCTION' ? 'Participar en subasta' : 'Comprar ahora'}</span><b>→</b></button>
  </article>;
}

function MarketBook({ listings, onOpen }: { listings: Listing[]; onOpen: (listing: Listing) => void }) {
  return <div className="market-book"><div className="book-row book-head"><span>Lado</span><span>Producto</span><span>Participante</span><span>Volumen</span><span>Lote mínimo</span><span>Precio</span><span>Vigencia</span><span /></div>{listings.map((listing) => <button className="book-row" key={listing.id} onClick={() => onOpen(listing)}><span><i className={`book-side ${listing.side.toLowerCase()}`}>{listing.side === 'SELL' ? 'Vende' : 'Compra'}</i></span><span><strong>{listing.product}</strong><small>{listing.variety} · {listing.quality}</small></span><span><strong>{listing.seller.displayName}</strong><small>{listing.seller.location}</small></span><span>{quantity.format(listing.availableQuantity)} {listing.unit}</span><span>{quantity.format(listing.minLot)} {listing.unit}</span><span><strong>{currency.format(listingPrice(listing))}</strong><small>por {listing.unit}</small></span><span>{listing.mechanism === 'AUCTION' ? remainingLabel(listing.endsAt) : shortDate(listing.endsAt)}</span><span className="row-arrow">→</span></button>)}</div>;
}

function ListingDialog({ listing, onClose, onComplete, live, user }: { listing: Listing; onClose: () => void; onComplete: (activity: Activity) => void; live: boolean; user: User | null }) {
  const base = listing.mechanism === 'AUCTION' ? (listing.currentPrice ?? listing.price) + (listing.bidIncrement ?? 1) : listing.price;
  const [bidPrice, setBidPrice] = useState(base); const [amount, setAmount] = useState(listing.minLot); const [working, setWorking] = useState(false); const [message, setMessage] = useState('');
  const total = amount * (listing.mechanism === 'AUCTION' ? bidPrice : listing.price);
  async function submit() {
    setWorking(true); setMessage('');
    try {
      if (live && !user) throw new Error('Debe ingresar para realizar esta operación.');
      if (listing.mechanism === 'AUCTION') {
        const id = live ? String(await placeBid(listing.id, bidPrice, amount)) : `demo-${Date.now()}`;
        setMessage(`Puja ${id.slice(0, 8).toUpperCase()} registrada. Queda vigente hasta el cierre; todavía no está adjudicada.`);
        return;
      }
      const id = listing.mechanism === 'FIXED'
        ? (live ? String(await buyNow(listing.id, amount)) : `demo-${Date.now()}`)
        : (live ? String(await supplyBuyOrder(listing.id, amount)) : `demo-${Date.now()}`);
      setMessage(`Operación ${id.slice(0, 8).toUpperCase()} creada correctamente.`);
      onComplete({ id: id.slice(0, 8).toUpperCase(), side: listing.side === 'BUY' ? 'SELL' : 'BUY', product: `${listing.product} ${listing.variety}`, counterparty: listing.seller.displayName, quantity: amount, unit: listing.unit, total, status: 'Pago por confirmar', updatedAt: 'Ahora' });
    } catch (error) { setMessage(error instanceof Error ? error.message : 'No fue posible registrar la operación.'); }
    finally { setWorking(false); }
  }
  return <div className="modal-backdrop" role="presentation" onMouseDown={onClose}><section className="listing-dialog" role="dialog" aria-modal="true" aria-label={`Detalle de ${listing.product}`} onMouseDown={(event) => event.stopPropagation()}><button className="modal-close" onClick={onClose} aria-label="Cerrar">×</button>
    <div className="dialog-kicker"><span className={`side-pill ${listing.side.toLowerCase()}`}>{sideLabel(listing)}</span><span>{mechanismLabel(listing)}</span><span>Vigente · {listing.mechanism === 'AUCTION' ? remainingLabel(listing.endsAt) : `hasta ${shortDate(listing.endsAt)}`}</span></div>
    <div className="dialog-title"><div><p>{listing.variety} · {listing.quality}</p><h2>{listing.product}</h2></div><div className="dialog-price"><span>{listing.side === 'BUY' ? 'Precio máximo' : listing.mechanism === 'AUCTION' ? 'Mejor oferta' : 'Precio unitario'}</span><strong>{currency.format(listingPrice(listing))}</strong><small>por {listing.unit}</small></div></div>
    <div className="dialog-layout"><div className="dialog-content"><section className="participant-profile"><div className="profile-top"><div className="participant-avatar large">{listing.seller.displayName.slice(0, 2).toUpperCase()}</div><div><VerifiedBadge /><h3>{listing.seller.displayName}</h3><p>{listing.seller.location} · Perfil comercial visible</p></div><span className="profile-tier">{listing.seller.tier}</span></div><div className="reputation-grid"><div><strong>{listing.seller.rating.toFixed(1)} ★</strong><span>Reputación</span></div><div><strong>{listing.seller.operations}</strong><span>Operaciones</span></div><div><strong>{listing.seller.completionRate}%</strong><span>Cumplimiento</span></div><div><strong>{listing.seller.qualityScore}%</strong><span>Conformidad</span></div></div></section>
      <section className="detail-section"><div className="section-label">Especificación comercial</div><dl className="detail-grid"><div><dt>Producto</dt><dd>{listing.product} · {listing.variety}</dd></div><div><dt>Calidad</dt><dd>{listing.quality}</dd></div><div><dt>Cantidad disponible</dt><dd>{quantity.format(listing.availableQuantity)} {listing.unit}</dd></div><div><dt>Lote mínimo</dt><dd>{quantity.format(listing.minLot)} {listing.unit}</dd></div><div><dt>Ubicación</dt><dd>{listing.comuna}, {listing.region}</dd></div><div><dt>Entrega</dt><dd>{listing.availability}</dd></div></dl><p className="listing-description">{listing.description}</p><a className="odepa-link" href="https://joacolk-maker.github.io/campo-claro-odepa/" target="_blank" rel="noreferrer">Abrir referencia de precios ODEPA <span>↗</span></a></section>
      <section className="commitment-flow"><div className="section-label">Trazabilidad de la operación</div><div><span className="done">1</span><p><strong>Términos publicados</strong><small>Precio, cantidad, calidad y ubicación registrados.</small></p><i /><span>2</span><p><strong>Adjudicación</strong><small>La contraparte acepta o gana la subasta.</small></p><i /><span>3</span><p><strong>Entrega y conformidad</strong><small>Evidencia, recepción y reputación final.</small></p></div></section>
    </div><aside className="transaction-panel"><div className="transaction-panel-head"><span>Orden vinculante</span><i>Registro auditable</i></div>{listing.mechanism === 'AUCTION' && <label>Oferta por {listing.unit}<input type="number" min={base} step={listing.bidIncrement ?? 1} value={bidPrice} onChange={(event) => setBidPrice(Number(event.target.value))} /><small>Mínimo {currency.format(base)} · incremento {currency.format(listing.bidIncrement ?? 1)}</small></label>}<label>Cantidad a operar<input type="number" min={listing.minLot} step={listing.minLot} max={listing.availableQuantity} value={amount} onChange={(event) => setAmount(Number(event.target.value))} /><small>Mínimo {quantity.format(listing.minLot)} {listing.unit}</small></label><div className="order-summary"><span>Precio unitario<b>{currency.format(listing.mechanism === 'AUCTION' ? bidPrice : listing.price)}</b></span><span>Cantidad<b>{quantity.format(amount)} {listing.unit}</b></span><span className="total">Valor total estimado<strong>{currency.format(total)}</strong></span></div><button className="transaction-action" disabled={working || amount < listing.minLot || amount > listing.availableQuantity} onClick={submit}>{working ? 'Registrando…' : listing.mechanism === 'AUCTION' ? 'Confirmar oferta' : listing.side === 'BUY' ? 'Ofrecer abastecimiento' : 'Reservar compra'} <span>→</span></button>{message && <div className="transaction-message">{message}</div>}<p className="binding-note"><i>✓</i> Al confirmar acepta precio, cantidad y condiciones. El nombre comercial, reputación y ubicación general de ambas partes permanecen visibles.</p></aside></div>
  </section></div>;
}

type Draft = { side: 'SELL' | 'BUY'; mechanism: 'FIXED' | 'AUCTION' | 'BUY_ORDER'; product: string; variety: string; quality: string; unit: string; region: string; comuna: string; totalQuantity: number; minLot: number; price: number; bidIncrement: number; durationHours: number; description: string; availability: string; availabilityMode: 'NOW' | 'FUTURE'; fulfillmentDate: string; partialFills: boolean };
const EMPTY_DRAFT: Draft = { side: 'SELL', mechanism: 'FIXED', product: '', variety: '', quality: '', unit: '', region: 'Región Metropolitana', comuna: '', totalQuantity: 1000, minLot: 100, price: 0, bidIncrement: 10, durationHours: 336, description: '', availability: '', availabilityMode: 'NOW', fulfillmentDate: '', partialFills: true };

function PublishDialog({ onClose, onCreated, live, user, onRequireLogin }: { onClose: () => void; onCreated: (listing: Listing) => void; live: boolean; user: User | null; onRequireLogin: () => void }) {
  const [draft, setDraft] = useState<Draft>(EMPTY_DRAFT); const [step, setStep] = useState(1); const [message, setMessage] = useState(''); const [working, setWorking] = useState(false); const [accepted, setAccepted] = useState(false); const [receipt, setReceipt] = useState<{ id: string; side: Draft['side']; product: string; total: number } | null>(null); const [catalog, setCatalog] = useState(fallbackCatalog); const [catalogState, setCatalogState] = useState<'loading' | 'ready' | 'fallback'>('loading');
  const set = <K extends keyof Draft>(key: K, value: Draft[K]) => setDraft((current) => ({ ...current, [key]: value }));
  useEffect(() => { let active = true; void loadMarketCatalog().then((data) => { if (active) { setCatalog(data); setCatalogState('ready'); } }).catch(() => { if (active) setCatalogState('fallback'); }); return () => { active = false; }; }, []);
  const varietyOptions = draft.product ? Object.keys(catalog[draft.product] ?? {}) : []; const qualityOptions = draft.product && draft.variety ? catalog[draft.product]?.[draft.variety] ?? [] : [];
  const durationOptions = draft.mechanism === 'AUCTION' ? [[24, '24 horas'], [48, '48 horas'], [72, '72 horas'], [168, '7 días']] as const : draft.side === 'BUY' ? [[168, '7 días'], [336, '14 días'], [720, '30 días']] as const : [[168, '7 días'], [336, '14 días'], [720, '30 días'], [1080, '45 días']] as const;
  const dateRequired = draft.side === 'BUY' || draft.availabilityMode === 'FUTURE';
  function nextStep() { setMessage(''); if (step === 1 && (!draft.product || !draft.variety || !draft.quality || !draft.unit || !draft.comuna || draft.totalQuantity <= 0 || draft.minLot <= 0 || draft.minLot > draft.totalQuantity)) { setMessage('Complete producto, presentación, ubicación y cantidades válidas.'); return; } if (step === 2 && (draft.price <= 0 || draft.durationHours <= 0 || (draft.mechanism === 'AUCTION' && draft.bidIncrement <= 0))) { setMessage('Indique un precio, incremento y vigencia válidos.'); return; } setStep((current) => Math.min(3, current + 1)); }
  async function submit(event: FormEvent) {
    event.preventDefault(); setWorking(true); setMessage('');
    try {
      if (live && !user) throw new Error('Debe ingresar y completar su verificación antes de publicar.');
      if (dateRequired && !draft.fulfillmentDate) throw new Error('Indique la fecha estimada.');
      if (!accepted) throw new Error('Debe aceptar que la publicación constituye una oferta comercial.');
      const endsAt = new Date(Date.now() + draft.durationHours * 3_600_000).toISOString();
      const timing = draft.side === 'BUY' ? `Entrega requerida: ${displayDate(draft.fulfillmentDate)}` : draft.availabilityMode === 'NOW' ? 'Disponible ahora' : `Cosecha estimada: ${displayDate(draft.fulfillmentDate)}`;
      const availability = [timing, draft.availability.trim()].filter(Boolean).join(' · ');
      const id = live ? String(await publishListing({ ...draft, availability, endsAt })) : `demo-${Date.now()}`;
      const listing: Listing = { id, side: draft.side, mechanism: draft.side === 'BUY' ? 'BUY_ORDER' : draft.mechanism, product: draft.product, variety: draft.variety, quality: draft.quality, unit: draft.unit, region: draft.region, comuna: draft.comuna, totalQuantity: draft.totalQuantity, availableQuantity: draft.totalQuantity, minLot: draft.minLot, price: draft.price, currentPrice: draft.mechanism === 'AUCTION' ? draft.price : undefined, bidIncrement: draft.mechanism === 'AUCTION' ? draft.bidIncrement : undefined, bidCount: 0, endsAt, availability, description: draft.description || 'Publicación ingresada por un usuario verificado.', partialFills: draft.partialFills, fulfillmentDate: draft.fulfillmentDate || undefined, availabilityMode: draft.availabilityMode, createdAt: new Date().toISOString(), status: 'ACTIVE', seller: { id: user?.id ?? 'demo-user', displayName: draft.side === 'BUY' ? 'Comprador piloto' : 'Productor piloto', location: `${draft.comuna}, ${draft.region}`, verified: true, rating: 5, operations: 0, completionRate: 100, qualityScore: 100, tier: 'Verificado' } };
      onCreated(listing);
      setReceipt({ id, side: draft.side, product: draft.product, total: draft.price * draft.totalQuantity });
    } catch (error) { setMessage(error instanceof Error ? error.message : 'No fue posible publicar.'); }
    finally { setWorking(false); }
  }

  if (receipt) return <div className="modal-backdrop" role="presentation" onMouseDown={onClose}><section className="publish-receipt" role="dialog" aria-modal="true" onMouseDown={(event) => event.stopPropagation()}><button type="button" className="modal-close" onClick={onClose} aria-label="Cerrar">×</button><div className="receipt-mark">✓</div><p className="eyebrow">Orden registrada</p><h2>{receipt.side === 'BUY' ? 'Su demanda quedó publicada.' : 'Su oferta quedó publicada.'}</h2><p>La orden fue almacenada en Campo Lindo y ya tiene un identificador auditable.</p><div className="receipt-code"><span>Identificador</span><strong>{receipt.id.slice(0, 8).toUpperCase()}</strong></div><dl><div><dt>Producto</dt><dd>{receipt.product}</dd></div><div><dt>Valor referencial</dt><dd>{currency.format(receipt.total)}</dd></div><div><dt>Estado</dt><dd>Activa</dd></div></dl><div className="receipt-actions"><Link href="/cuenta">Ver en Mis órdenes</Link><button type="button" onClick={onClose}>Volver al mercado</button></div><small>Este comprobante confirma que la publicación fue persistida. Puede revisarla en cualquier momento desde Mi mercado.</small></section></div>;
  return <div className="modal-backdrop" role="presentation" onMouseDown={onClose}><form className="publish-dialog" onSubmit={submit} onMouseDown={(event) => event.stopPropagation()}><button type="button" className="modal-close" onClick={onClose} aria-label="Cerrar">×</button><header className="publish-header"><div><p className="eyebrow">Nueva orden de mercado</p><h2>Publique con términos <em>claros y comparables.</em></h2></div><div className="publish-progress"><span className={step >= 1 ? 'active' : ''}><i>1</i>Producto y lote</span><b /><span className={step >= 2 ? 'active' : ''}><i>2</i>Precio</span><b /><span className={step >= 3 ? 'active' : ''}><i>3</i>Entrega</span></div></header>
    <div className="publish-layout"><div className="publish-main">{step === 1 && <><div className="publish-choice"><button type="button" className={draft.side === 'SELL' ? 'active' : ''} onClick={() => setDraft((current) => ({ ...current, side: 'SELL', mechanism: 'FIXED', durationHours: 336, fulfillmentDate: '' }))}><i>↑</i><span><strong>Quiero vender</strong><small>Publicar oferta disponible</small></span></button><button type="button" className={draft.side === 'BUY' ? 'active' : ''} onClick={() => setDraft((current) => ({ ...current, side: 'BUY', mechanism: 'BUY_ORDER', durationHours: 336, fulfillmentDate: '' }))}><i>↓</i><span><strong>Quiero comprar</strong><small>Publicar necesidad de abastecimiento</small></span></button></div><div className="form-section"><h3>Especificación del producto</h3><div className="publish-grid"><label>Producto<select required value={draft.product} onChange={(e) => setDraft((current) => ({ ...current, product: e.target.value, variety: '', quality: '' }))}><option value="">Seleccione producto</option>{PRODUCTS.map((item) => <option key={item}>{item}</option>)}</select><small>{catalogState === 'loading' ? 'Cargando catálogo ODEPA…' : catalogState === 'fallback' ? 'Catálogo básico disponible' : 'Catálogo ODEPA conectado'}</small></label><label>Variedad<select required disabled={!draft.product} value={draft.variety} onChange={(e) => setDraft((current) => ({ ...current, variety: e.target.value, quality: '' }))}><option value="">{draft.product ? 'Seleccione variedad' : 'Primero seleccione producto'}</option>{varietyOptions.map((item) => <option key={item}>{item}</option>)}</select></label><label>Calidad<select required disabled={!draft.variety} value={draft.quality} onChange={(e) => set('quality', e.target.value)}><option value="">{draft.variety ? 'Seleccione calidad' : 'Primero seleccione variedad'}</option>{qualityOptions.map((item) => <option key={item}>{item}</option>)}</select></label><label>Unidad comercial<input required value={draft.unit} onChange={(e) => set('unit', e.target.value)} placeholder="Ej. malla 20 kg" /></label></div></div><div className="form-section"><h3>Lote y ubicación</h3><div className="publish-grid"><label>Cantidad total<input type="number" min="1" value={draft.totalQuantity} onChange={(e) => set('totalQuantity', Number(e.target.value))} /></label><label>Lote mínimo<input type="number" min="1" value={draft.minLot} onChange={(e) => set('minLot', Number(e.target.value))} /></label><label>Región<select value={draft.region} onChange={(e) => set('region', e.target.value)}>{REGIONS.map((item) => <option key={item}>{item}</option>)}</select></label><label>Comuna<input required value={draft.comuna} onChange={(e) => set('comuna', e.target.value)} placeholder="Ubicación general" /></label><label className="check-label"><input type="checkbox" checked={draft.partialFills} onChange={(e) => set('partialFills', e.target.checked)} /><span><strong>Aceptar adjudicaciones parciales</strong><small>Permite vender o abastecer el lote en más de una operación.</small></span></label></div></div></>}
      {step === 2 && <><div className="form-section"><h3>Mecanismo de adjudicación</h3>{draft.side === 'SELL' ? <div className="mechanism-choice"><button type="button" className={draft.mechanism === 'FIXED' ? 'active' : ''} onClick={() => setDraft((current) => ({ ...current, mechanism: 'FIXED', durationHours: 336 }))}><strong>Compra inmediata</strong><small>El primer comprador que acepta el precio reserva el lote.</small></button><button type="button" className={draft.mechanism === 'AUCTION' ? 'active' : ''} onClick={() => setDraft((current) => ({ ...current, mechanism: 'AUCTION', durationHours: 48 }))}><strong>Subasta abierta</strong><small>Gana la mejor oferta válida al cierre.</small></button></div> : <div className="buy-order-explainer"><i>↓</i><div><strong>Orden de compra</strong><p>Los productores podrán ofrecer abastecimiento hasta su precio máximo.</p></div></div>}</div><div className="form-section"><h3>Precio y vigencia</h3><div className="publish-grid"><label>{draft.side === 'BUY' ? 'Precio máximo' : draft.mechanism === 'AUCTION' ? 'Precio inicial' : 'Precio publicado'}<div className="money-input"><span>$</span><input type="number" min="1" value={draft.price || ''} onChange={(e) => set('price', Number(e.target.value))} placeholder="0" /></div><small>Por {draft.unit || 'unidad comercial'}</small></label>{draft.mechanism === 'AUCTION' && <label>Incremento mínimo<div className="money-input"><span>$</span><input type="number" min="1" value={draft.bidIncrement} onChange={(e) => set('bidIncrement', Number(e.target.value))} /></div></label>}<label>{draft.mechanism === 'AUCTION' ? 'Duración de subasta' : 'Vigencia de publicación'}<select value={draft.durationHours} onChange={(e) => set('durationHours', Number(e.target.value))}>{durationOptions.map(([hours, label]) => <option value={hours} key={hours}>{label}</option>)}</select></label></div></div><div className="odepa-callout"><span>ODEPA</span><div><strong>Use una referencia antes de fijar el precio.</strong><p>Compare el mismo producto, variedad, calidad, unidad y mercado; no mezcle series incompatibles.</p></div><a href="https://joacolk-maker.github.io/campo-claro-odepa/" target="_blank" rel="noreferrer">Abrir analítica ↗</a></div></>}
      {step === 3 && <><div className="form-section"><h3>Disponibilidad y entrega</h3><div className="publish-grid">{draft.side === 'SELL' && <label>Disponibilidad<select value={draft.availabilityMode} onChange={(e) => setDraft((current) => ({ ...current, availabilityMode: e.target.value as Draft['availabilityMode'], fulfillmentDate: '' }))}><option value="NOW">Disponible ahora</option><option value="FUTURE">Cosecha futura</option></select></label>}{dateRequired && <label>{draft.side === 'SELL' ? 'Fecha estimada de cosecha' : 'Fecha requerida de entrega'}<input required type="date" min={today()} value={draft.fulfillmentDate} onChange={(e) => set('fulfillmentDate', e.target.value)} /></label>}<label className="wide">Condiciones logísticas<input value={draft.availability} onChange={(e) => set('availability', e.target.value)} placeholder={draft.side === 'SELL' ? 'Retiro en predio, horario, carga y ventana estimada' : 'Lugar de recepción, horario y tolerancia de fecha'} /></label><label className="wide">Descripción y tolerancias<textarea value={draft.description} onChange={(e) => set('description', e.target.value)} placeholder="Calibre, envase, estado, humedad, tolerancias y cualquier condición relevante…" /></label></div></div><label className="accept-box"><input type="checkbox" checked={accepted} onChange={(e) => setAccepted(e.target.checked)} /><span><strong>Acepto publicar una oferta comercial con términos registrados.</strong><small>La adjudicación crea un compromiso entre participantes identificados. Las modificaciones posteriores quedan limitadas.</small></span></label>{!user && live && <button type="button" className="login-before-publish" onClick={onRequireLogin}>Ingresar o crear cuenta para publicar <span>→</span></button>}</>}
      {message && <div className="form-message">{message}</div>}<div className="publish-actions">{step > 1 ? <button type="button" className="secondary" onClick={() => { setStep((current) => current - 1); setMessage(''); }}>← Volver</button> : <span />}{step < 3 ? <button type="button" className="primary" onClick={nextStep}>Continuar <span>→</span></button> : <button className="primary" disabled={working || !accepted || (dateRequired && !draft.fulfillmentDate) || (live && !user)}>{working ? 'Publicando…' : 'Publicar orden'} <span>→</span></button>}</div>
    </div><aside className="draft-summary"><span className="draft-status">Borrador · Paso {step} de 3</span><h3>Resumen de orden</h3><div className="draft-product"><span>{draft.product ? draft.product.slice(0, 2).toUpperCase() : '—'}</span><div><strong>{draft.product || 'Producto pendiente'}</strong><small>{[draft.variety, draft.quality].filter(Boolean).join(' · ') || 'Complete la especificación'}</small></div></div><dl><div><dt>Lado</dt><dd>{draft.side === 'SELL' ? 'Oferta de venta' : 'Demanda de compra'}</dd></div><div><dt>Mecanismo</dt><dd>{draft.side === 'BUY' ? 'Orden de compra' : draft.mechanism === 'AUCTION' ? 'Subasta abierta' : 'Compra inmediata'}</dd></div><div><dt>Cantidad</dt><dd>{quantity.format(draft.totalQuantity)} {draft.unit || 'unidades'}</dd></div><div><dt>Lote mínimo</dt><dd>{quantity.format(draft.minLot)} {draft.unit || 'unidades'}</dd></div><div><dt>Precio</dt><dd>{draft.price ? `${currency.format(draft.price)} / ${draft.unit || 'unidad'}` : 'Pendiente'}</dd></div><div><dt>Ubicación</dt><dd>{draft.comuna ? `${draft.comuna}, ${draft.region.replace('Región de ', '')}` : 'Pendiente'}</dd></div></dl><div className="draft-value"><span>Valor total referencial</span><strong>{draft.price ? currency.format(draft.price * draft.totalQuantity) : '—'}</strong><small>No incluye transporte ni impuestos.</small></div><p><i>✓</i> Visible sólo cuando todos los campos obligatorios estén completos.</p></aside></div>
  </form></div>;
}

type AuthMode = 'login' | 'register' | 'magic';
function LoginDialog({ onClose, user, access, onUserChange }: { onClose: () => void; user: User | null; access: MarketAccess | null; onUserChange: (user: User | null) => void }) {
  const [mode, setMode] = useState<AuthMode>('login'); const [displayName, setDisplayName] = useState(''); const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [message, setMessage] = useState(''); const [working, setWorking] = useState(false);
  async function submit(event: FormEvent) { event.preventDefault(); setWorking(true); setMessage(''); try { if (mode === 'magic') { await sendMagicLink(email); setMessage('Le enviamos un enlace seguro a su correo.'); } else if (mode === 'register') { const authenticated = await signUpWithPassword(displayName, email, password); if (authenticated) { onUserChange(authenticated); setMessage('Cuenta creada. La sesión quedó iniciada.'); } else setMessage('Cuenta creada. Revise su correo una sola vez para confirmar la dirección.'); } else { const authenticated = await signInWithPassword(email, password); onUserChange(authenticated); setMessage('Sesión iniciada correctamente.'); } } catch (error) { setMessage(error instanceof Error ? error.message : 'No fue posible completar el acceso.'); } finally { setWorking(false); } }
  async function closeSession() { setWorking(true); setMessage(''); try { await signOut(); onUserChange(null); onClose(); } catch (error) { setMessage(error instanceof Error ? error.message : 'No fue posible cerrar la sesión.'); setWorking(false); } }
  if (user) return <div className="modal-backdrop" role="presentation" onMouseDown={onClose}><section className="login-dialog account-dialog" role="dialog" aria-modal="true" onMouseDown={(event) => event.stopPropagation()}><button type="button" className="modal-close" onClick={onClose}>×</button><div className="account-mark">✓</div><p className="eyebrow">Sesión activa</p><h2>Mi cuenta</h2><strong className="account-email">{user.email}</strong><div className={`verification-card${access?.verified ? ' is-verified' : ''}`}><span>Estado de operación</span><strong>{access?.verified ? 'Identidad verificada' : access?.verificationStatus === 'IN_REVIEW' ? 'Verificación en revisión' : 'Verificación pendiente'}</strong><p>{access?.verified ? 'Su cuenta está habilitada para publicar y operar.' : 'Campo Lindo debe aprobar su identidad comercial antes de aceptar órdenes o pujas.'}</p></div><Link className="account-market-link" href="/cuenta">Abrir Mis órdenes y operaciones <span>→</span></Link>{access?.isAdmin && <Link className="account-admin-link" href="/admin">Abrir mantenedor Campo Lindo <span>→</span></Link>}<button type="button" className="auth-primary signout" disabled={working} onClick={closeSession}>{working ? 'Cerrando…' : 'Cerrar sesión'}</button>{message && <div className="transaction-message">{message}</div>}</section></div>;
  return <div className="modal-backdrop" role="presentation" onMouseDown={onClose}><form className="login-dialog" onSubmit={submit} onMouseDown={(event) => event.stopPropagation()}><button type="button" className="modal-close" onClick={onClose}>×</button><LogoMark /><p className="eyebrow">Acceso seguro</p><h2>{mode === 'register' ? 'Cree su cuenta comercial.' : mode === 'magic' ? 'Acceso por enlace.' : 'Bienvenido a Campo Lindo.'}</h2><p className="auth-intro">Una identidad por empresa o productor. Cada operación construye reputación verificable.</p>{mode !== 'magic' && <div className="auth-tabs"><button type="button" className={mode === 'login' ? 'active' : ''} onClick={() => { setMode('login'); setMessage(''); }}>Ingresar</button><button type="button" className={mode === 'register' ? 'active' : ''} onClick={() => { setMode('register'); setMessage(''); }}>Crear cuenta</button></div>}{mode === 'register' && <label>Nombre o razón social<input required value={displayName} onChange={(e) => setDisplayName(e.target.value)} placeholder="Nombre comercial" /></label>}<label>Correo electrónico<input type="email" autoComplete="email" required value={email} onChange={(e) => setEmail(e.target.value)} placeholder="nombre@empresa.cl" /></label>{mode !== 'magic' && <label>Contraseña<input type="password" autoComplete={mode === 'register' ? 'new-password' : 'current-password'} minLength={8} required value={password} onChange={(e) => setPassword(e.target.value)} placeholder="Mínimo 8 caracteres" /></label>}<button className="auth-primary" disabled={working}>{working ? 'Procesando…' : mode === 'register' ? 'Crear cuenta' : mode === 'magic' ? 'Enviar enlace seguro' : 'Ingresar'} <span>→</span></button><button type="button" className="magic-option" onClick={() => { setMode(mode === 'magic' ? 'login' : 'magic'); setMessage(''); }}>{mode === 'magic' ? 'Volver al acceso con contraseña' : 'Prefiero recibir un enlace por correo'}</button><div className="auth-security"><span>✓ Datos cifrados</span><span>✓ Perfiles verificados</span><span>✓ Operaciones auditables</span></div>{message && <div className="transaction-message">{message}</div>}</form></div>;
}

export default function Home() {
  const [listings, setListings] = useState<Listing[]>([]); const [source, setSource] = useState<'loading' | 'live' | 'demo' | 'error'>('loading'); const [user, setUser] = useState<User | null>(null); const [access, setAccess] = useState<MarketAccess | null>(null); const [modal, setModal] = useState<Modal>(null); const [selected, setSelected] = useState<Listing | null>(null); const [product, setProduct] = useState('Todos los productos'); const [region, setRegion] = useState('Todas las regiones'); const [marketSide, setMarketSide] = useState<'ALL' | 'SELL' | 'BUY'>('ALL'); const [mode, setMode] = useState('Todas las modalidades'); const [query, setQuery] = useState(''); const [sort, setSort] = useState<SortMode>('closing'); const [view, setView] = useState<ViewMode>('cards'); const [activities, setActivities] = useState<Activity[]>([]); const [, setTick] = useState(0);
  useEffect(() => {
    let active = true;
    const params = new URLSearchParams(window.location.search);
    if (params.get('demo') === '1') {
      Promise.resolve().then(() => {
        if (!active) return;
        setListings(DEMO_LISTINGS);
        setActivities(DEMO_ACTIVITY);
        setSource('demo');
      });
    } else {
      loadListings().then((data) => {
        if (!active) return;
        setListings(data);
        setActivities([]);
        setSource('live');
      }).catch(() => {
        if (!active) return;
        setListings([]);
        setActivities([]);
        setSource('error');
      });
      currentUser().then((authenticated) => {
        if (active) setUser(authenticated);
      }).catch(() => {
        if (active) setUser(null);
      });
    }
    if (params.get('publicar') === '1') Promise.resolve().then(() => { if (active) setModal('publish'); });
    return () => { active = false; };
  }, []);
  useEffect(() => { let active = true; if (!user) return; Promise.all([loadActivities(user.id), loadMarketAccess()]).then(([items, marketAccess]) => { if (!active) return; setActivities(items); setAccess(marketAccess); }).catch(() => undefined); return () => { active = false; }; }, [user]);
  useEffect(() => { const timer = window.setInterval(() => setTick((v) => v + 1), 60_000); return () => window.clearInterval(timer); }, []);
  useEffect(() => { const context = document.modelContext; if (!context?.registerTool) return; const lifecycle = new AbortController(); const register = async () => { await context.registerTool({ name: 'search_market', title: 'Buscar en el mercado', description: 'Filtra las publicaciones visibles por producto, región, lado y modalidad.', inputSchema: { type: 'object', properties: { product: { type: 'string', enum: PRODUCTS }, region: { type: 'string', enum: REGIONS }, side: { type: 'string', enum: ['ALL', 'SELL', 'BUY'] }, mechanism: { type: 'string', enum: ['ALL', 'FIXED', 'AUCTION', 'BUY_ORDER'] } }, additionalProperties: false }, annotations: { readOnlyHint: true, untrustedContentHint: true }, execute(input) { const request = (input ?? {}) as { product?: string; region?: string; side?: 'ALL' | 'SELL' | 'BUY'; mechanism?: 'ALL' | 'FIXED' | 'AUCTION' | 'BUY_ORDER' }; setProduct(request.product && (PRODUCTS as readonly string[]).includes(request.product) ? request.product : 'Todos los productos'); setRegion(request.region && (REGIONS as readonly string[]).includes(request.region) ? request.region : 'Todas las regiones'); setMarketSide(request.side ?? 'ALL'); setMode(!request.mechanism || request.mechanism === 'ALL' ? 'Todas las modalidades' : request.mechanism); window.location.hash = 'mercado'; return { opened: true }; } }, { signal: lifecycle.signal }); await context.registerTool({ name: 'start_listing_publication', title: 'Iniciar publicación', description: 'Abre el formulario visible para preparar una nueva oferta o demanda; no publica ni compromete una operación.', inputSchema: { type: 'object', properties: {}, additionalProperties: false }, annotations: { readOnlyHint: false, untrustedContentHint: false }, execute() { setModal('publish'); return { opened: true, submitted: false }; } }, { signal: lifecycle.signal }); }; void register().catch(() => undefined); return () => lifecycle.abort(); }, []);
  const filtered = useMemo(() => listings.filter((item) => (product === 'Todos los productos' || item.product === product) && (region === 'Todas las regiones' || item.region === region) && (marketSide === 'ALL' || item.side === marketSide) && (mode === 'Todas las modalidades' || item.mechanism === mode) && (!query || `${item.product} ${item.variety} ${item.quality} ${item.seller.displayName} ${item.comuna}`.toLowerCase().includes(query.toLowerCase()))).sort((a, b) => { if (sort === 'price-low') return listingPrice(a) - listingPrice(b); if (sort === 'price-high') return listingPrice(b) - listingPrice(a); if (sort === 'reputation') return b.seller.rating - a.seller.rating; if (sort === 'recent') return b.id.localeCompare(a.id); return new Date(a.endsAt).getTime() - new Date(b.endsAt).getTime(); }), [listings, product, region, marketSide, mode, query, sort]);
  const stats = useMemo(() => ({ offers: listings.filter((item) => item.side === 'SELL').length, demand: listings.filter((item) => item.side === 'BUY').length, auctions: listings.filter((item) => item.mechanism === 'AUCTION').length, participants: new Set(listings.map((item) => item.seller.id)).size }), [listings]);
  const pulse = stats.offers === stats.demand ? 'Mercado equilibrado' : stats.offers > stats.demand ? 'Mayor oferta publicada' : 'Mayor demanda publicada';
  function handleUserChange(nextUser: User | null) { setUser(nextUser); if (!nextUser) { setAccess(null); setActivities([]); } }
  function openListing(item: Listing) { setSelected(item); setModal('listing'); } function resetFilters() { setProduct('Todos los productos'); setRegion('Todas las regiones'); setMarketSide('ALL'); setMode('Todas las modalidades'); setQuery(''); }
  return <main><div className="pilot-strip"><span><i /> Piloto transaccional Campo Lindo</span><p>Operaciones reales sólo entre perfiles verificados. Pagos y garantías económicas: próxima etapa.</p></div><header className="topbar"><a className="brand" href="#inicio"><LogoMark /><span>Campo Lindo<small>Mercado agrícola</small></span></a><nav><a href="#mercado">Mercado</a><a href="#cumplimiento">Cómo operamos</a>{user ? <Link href="/cuenta">Mis órdenes</Link> : <a href="#actividad">Mis operaciones</a>}{access?.isAdmin && <Link href="/admin">Mantenedor</Link>}</nav><div className="header-actions"><a className="odepa-nav" href="https://joacolk-maker.github.io/campo-claro-odepa/" target="_blank" rel="noreferrer"><span>ODEPA</span> Analítica ↗</a><button className="login-button" onClick={() => setModal('login')}>{user ? 'Mi cuenta' : 'Ingresar'}</button><button className="publish-button" onClick={() => setModal('publish')}>+ Publicar</button></div></header>
    <section className="hero" id="inicio"><div className="hero-copy"><p className="eyebrow"><span /> Oferta, demanda y adjudicación</p><h1>Un mercado agrícola donde <em>la palabra queda registrada.</em></h1><p>Publique productos, encuentre contraparte y cierre operaciones con precio, calidad, cantidad, ubicación y fecha claramente definidos.</p><div className="hero-actions"><button onClick={() => setModal('publish')}>Publicar oferta o demanda <span>→</span></button><a href="#mercado">Ver libro de mercado</a></div><div className="hero-trust"><span><b>✓</b> Identidad visible</span><span><b>✓</b> Reputación verificable</span><span><b>✓</b> Términos auditables</span></div></div><aside className="market-terminal"><header><div><i /><span>Campo Lindo Market</span></div><b>{source === 'live' ? 'EN LÍNEA' : source === 'loading' ? 'CONECTANDO' : source === 'demo' ? 'DEMO' : 'SIN CONEXIÓN'}</b></header><div className="terminal-pulse"><span>Estado del libro</span><strong>{source === 'error' ? 'Conexión no disponible' : pulse}</strong><small>{source === 'error' ? 'Reintente para actualizar el libro' : 'Actualizado con publicaciones activas'}</small></div><div className="terminal-grid"><div><span>Ofertas</span><strong>{stats.offers}</strong><i className="up">VENTA</i></div><div><span>Demandas</span><strong>{stats.demand}</strong><i className="down">COMPRA</i></div><div><span>Subastas</span><strong>{stats.auctions}</strong><i>ABIERTAS</i></div><div><span>Participantes</span><strong>{stats.participants}</strong><i>VISIBLES</i></div></div><footer><span><i /> Base transaccional Supabase</span><span>Catálogo ODEPA conectado</span></footer></aside></section>
    <section className="assurance-bar"><div><span>01</span><p><strong>Participantes identificados</strong><small>Nombre comercial, ubicación general e historial visibles.</small></p></div><div><span>02</span><p><strong>Términos comparables</strong><small>Producto, variedad y calidad normalizados con ODEPA.</small></p></div><div><span>03</span><p><strong>Compromiso trazable</strong><small>Cada puja, reserva y cambio de estado queda registrado.</small></p></div></section>
    <section className="market-section" id="mercado"><div className="section-heading"><div><p className="eyebrow">Libro de mercado</p><h2>Precios reales. <em>Contrapartes visibles.</em></h2><p>Explore ofertas de venta, órdenes de compra y subastas activas.</p></div><button onClick={() => setModal('publish')}>+ Nueva publicación</button></div><div className="market-toolbar"><div className="search-field"><span>⌕</span><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Buscar producto, variedad, participante o comuna" /></div><div className="side-tabs"><button className={marketSide === 'ALL' ? 'active' : ''} onClick={() => setMarketSide('ALL')}>Todo <b>{listings.length}</b></button><button className={marketSide === 'SELL' ? 'active sell' : ''} onClick={() => setMarketSide('SELL')}>Ofertas <b>{stats.offers}</b></button><button className={marketSide === 'BUY' ? 'active buy' : ''} onClick={() => setMarketSide('BUY')}>Demandas <b>{stats.demand}</b></button></div><div className="view-toggle"><button className={view === 'cards' ? 'active' : ''} onClick={() => setView('cards')} aria-label="Vista tarjetas">▦</button><button className={view === 'book' ? 'active' : ''} onClick={() => setView('book')} aria-label="Vista libro">☷</button></div></div><div className="filter-row"><label>Producto<select value={product} onChange={(e) => setProduct(e.target.value)}><option>Todos los productos</option>{PRODUCTS.map((item) => <option key={item}>{item}</option>)}</select></label><label>Región<select value={region} onChange={(e) => setRegion(e.target.value)}><option>Todas las regiones</option>{REGIONS.map((item) => <option key={item}>{item}</option>)}</select></label><label>Modalidad<select value={mode} onChange={(e) => setMode(e.target.value)}><option>Todas las modalidades</option><option value="FIXED">Compra inmediata</option><option value="AUCTION">Subasta abierta</option><option value="BUY_ORDER">Orden de compra</option></select></label><label>Ordenar por<select value={sort} onChange={(e) => setSort(e.target.value as SortMode)}><option value="closing">Cierre más próximo</option><option value="recent">Más recientes</option><option value="price-low">Menor precio</option><option value="price-high">Mayor precio</option><option value="reputation">Mejor reputación</option></select></label></div><div className="market-meta"><span><strong>{filtered.length}</strong> publicaciones encontradas</span><small>Precios expresados en la unidad comercial indicada. No compare unidades distintas.</small></div>{filtered.length ? view === 'cards' ? <div className="listings-grid">{filtered.map((item) => <ListingCard key={item.id} listing={item} onOpen={openListing} />)}</div> : <MarketBook listings={filtered} onOpen={openListing} /> : <div className="empty-market"><div className="empty-symbol"><i /><b /></div><p className="eyebrow">Sin coincidencias</p><h3>{listings.length ? 'No hay publicaciones para estos filtros.' : 'El libro está listo para su primera orden.'}</h3><p>{listings.length ? 'Cambie producto, región o modalidad para ampliar la búsqueda.' : 'Publique una oferta de venta o una necesidad de compra con condiciones verificables.'}</p><div><button onClick={() => setModal('publish')}>Crear publicación <span>→</span></button>{listings.length > 0 && <button className="secondary" onClick={resetFilters}>Limpiar filtros</button>}</div></div>}</section>
    <section className="commitment-section" id="cumplimiento"><div className="commitment-intro"><p className="eyebrow">Diseñado para cumplir</p><h2>Del precio publicado a la <em>entrega conforme.</em></h2><p>Campo Lindo no termina en el dato de contacto. Cada etapa deja evidencia y afecta la reputación comercial.</p><a href="#mercado">Explorar mercado <span>→</span></a></div><div className="commitment-map"><article><span>01</span><i>PUBLICACIÓN</i><h3>Términos completos</h3><p>Calidad, unidad, lote mínimo, precio, ubicación y fecha.</p><b>Oferta comparable</b></article><article><span>02</span><i>ADJUDICACIÓN</i><h3>Compromiso bilateral</h3><p>Compra inmediata, mejor puja u oferta de abastecimiento.</p><b>Orden registrada</b></article><article><span>03</span><i>COORDINACIÓN</i><h3>Entrega verificable</h3><p>Fecha, retiro, transporte y evidencia documental.</p><b>Hitos trazables</b></article><article><span>04</span><i>CIERRE</i><h3>Conformidad y reputación</h3><p>Cumplimiento de cantidad, calidad, plazo y contraparte.</p><b>Historial acumulativo</b></article></div></section>
    <section className="risk-section"><div className="risk-card featured"><span className="risk-icon">✓</span><div><p className="eyebrow">Confianza comercial</p><h3>La identidad no se esconde.</h3><p>Nombre o razón social, ubicación general, estado de verificación, historial y nivel de cumplimiento acompañan cada publicación.</p></div></div><div className="risk-card"><span className="risk-number">0–100</span><div><p className="eyebrow">Puntaje de cumplimiento</p><h3>La reputación se gana operación a operación.</h3><p>Entrega, conformidad de calidad, cancelaciones y disputas forman el historial del participante.</p></div></div><div className="risk-card"><span className="risk-icon outline">↗</span><div><p className="eyebrow">Próxima etapa</p><h3>Pago, garantía y transporte.</h3><p>La arquitectura contempla confirmación de pago, evidencia de entrega, disputa y logística de terceros.</p></div></div></section>
    <section className="activity-section" id="actividad"><div className="activity-heading"><div><p className="eyebrow">Centro de operaciones</p><h2>Mis compromisos</h2><p>Seguimiento de compras, ventas, entregas y estados pendientes.</p></div><button onClick={() => setModal('activity')}>Ver historial completo</button></div><div className="activity-shell"><div className="activity-row activity-header"><span>Operación</span><span>Producto</span><span>Contraparte</span><span>Valor</span><span>Estado</span></div>{activities.slice(0, 4).map((item) => <div className="activity-row" key={item.id}><strong>{item.id}<small>{item.updatedAt}</small></strong><span>{item.product}<small>{quantity.format(item.quantity)} {item.unit}</small></span><span>{item.counterparty}</span><b>{currency.format(item.total)}</b><i className={`status status-${item.status.toLowerCase().replaceAll(' ', '-')}`}>{item.status}</i></div>)}{!activities.length && <div className="activity-empty"><span>◎</span><strong>{source === 'live' && !user ? 'Ingrese para ver sus operaciones.' : 'Aún no registra operaciones.'}</strong><p>Cuando una oferta sea adjudicada aparecerá aquí con todos sus hitos.</p>{!user && <button onClick={() => setModal('login')}>Ingresar</button>}</div>}</div></section>
    <footer><div><a className="brand" href="#inicio"><LogoMark /><span>Campo Lindo<small>Mercado agrícola</small></span></a><p>Infraestructura digital para comercializar frutas y hortalizas con información, identidad y trazabilidad.</p></div><div><strong>Plataforma</strong><a href="#mercado">Mercado</a><a href="#cumplimiento">Cómo operamos</a><Link href="/cuenta">Mis órdenes</Link></div><div><strong>Información</strong><a href="https://joacolk-maker.github.io/campo-claro-odepa/" target="_blank" rel="noreferrer">Analítica ODEPA ↗</a><span>Piloto experimental</span><span>Chile · 2026</span></div><small>Los precios ODEPA son una referencia estadística y no constituyen una recomendación. Pagos, garantías y transporte aún no están habilitados.</small></footer>
    {modal === 'listing' && selected && <ListingDialog listing={selected} onClose={() => setModal(null)} live={source === 'live'} user={user} onComplete={(activity) => setActivities((current) => [activity, ...current])} />}{modal === 'publish' && <PublishDialog onClose={() => setModal(null)} live={source === 'live'} user={user} onRequireLogin={() => setModal('login')} onCreated={(listing) => { setListings((current) => [listing, ...current]); }} />}{modal === 'login' && <LoginDialog onClose={() => setModal(null)} user={user} access={access} onUserChange={handleUserChange} />}{modal === 'activity' && <div className="modal-backdrop" onMouseDown={() => setModal(null)}><section className="history-dialog" onMouseDown={(event) => event.stopPropagation()}><button className="modal-close" onClick={() => setModal(null)}>×</button><p className="eyebrow">Trazabilidad completa</p><h2>Historial de operaciones</h2>{activities.map((item) => <div className="history-row" key={item.id}><div><strong>{item.id} · {item.product}</strong><span>{item.counterparty} · {item.updatedAt}</span></div><div><b>{currency.format(item.total)}</b><i className="status">{item.status}</i></div></div>)}{!activities.length && <div className="activity-empty"><span>◎</span><strong>{source === 'live' && !user ? 'Ingrese para consultar su historial.' : 'Aún no hay operaciones registradas.'}</strong></div>}</section></div>}
  </main>;
}
